mapper.select:
SELECT sale.proof_images
FROM dms_shop_after_sale sale
INNER JOIN dms_shop_order scoped_order ON scoped_order.id = sale.order_id
WHERE COALESCE(scoped_order.tenant_id, 1) = #{tenantId}
  AND sale.member_id = #{memberId}
  AND sale.proof_images IS NOT NULL
  AND sale.proof_images != ''

  AND scoped_order.merchant_id = #{merchantId}

SELECT sale.id
FROM dms_shop_after_sale sale
INNER JOIN dms_shop_order scoped_order ON scoped_order.id = sale.order_id
WHERE sale.status = 4
  AND sale.audit_time IS NOT NULL
  AND sale.audit_time <= #{cutoff}
  AND COALESCE(scoped_order.tenant_id, 1) = #{tenantId}
ORDER BY sale.id
LIMIT #{limit}
